/**
 * Rachel at the Well
 * ------------------
 * At Haran Jacob rolls the stone from the well and waters Laban's flock for Rachel, and kisses her and weeps. Stage: a well in a highland pasture at noon, a great stone rolled aside, a shepherdess watering her sheep; a sudden meeting, water and tears.
 *
 * Palette 0x1a1024 → 0x060402 · light: dawn · hero: pillar
 *
 * Generated by scripts/add-shot-scenes.mjs from the act data and
 * the mood board in ../../art/. Composition follows the kit in
 * ./jacob-kit.js.
 */

import { THREE, createScene, water, cityGate, house, sheep, well, pillar, person, birds } from './jacob-kit.js';

const BG = 0x1a1024;
const GROUND = 0x060402;

export function build(group) {
    const W = createScene(group, { seed: 3969016156, bg: BG, fogNear: 55, fogFar: 220 });

    /* light — dawn */
    W.lights({ sky: 0x9ab4d0, gnd: 0x5a5a52, hemi: 0.75, sun: 0xffd9a0, sunI: 0.95, sunPos: [-45, 16, 26] });

    W.disc([-58, 30, -145], 9, 0xffd9a0);
    W.disc([-58, 30, -155], 16, 0xffb060, 0.22);
    W.stars(60, 150, [0xcfd8e8, 0xbfd0e0], 0.55);
    const clouds = W.grp(group, [0, 0, 0], { name: 'cloud_bank' });
    [[-60, 34, -120, 24], [10, 40, -135, 30], [70, 33, -125, 22]].forEach(([x, y, z, s]) => {
        W.add(clouds, W.G('ico', 1, 1), W.mat(0xd8c8b8, { opacity: 0.5 }), [x, y, z], { s: [s, s * 0.24, s * 0.5] });
    });
    W.backdrop(clouds);

    /* river: animated water between grassy banks */
    water(W, group, 260, 26, -0.4, 0x020101, 0x070502);
    W.ground(260, 95, 0, 60, 0x060402, { amp: 0.5, j: 0.3, flat: 24, fz: 54 });
    W.ground(260, 95, 0, -64, 0x050302, { amp: 0.6, j: 0.3, flat: 24, fz: -58 });
    W.add(group, W.G('box', 260, 0.3, 4), W.mat(0x030201), [0, -0.05, 12.6]);
    W.add(group, W.G('box', 260, 0.3, 4), W.mat(0x030201), [0, -0.05, -14.6]);

    /* city: gate, towers and houses on the far side */
    const city = W.grp(group, [17, 0, -58], { name: 'city', r: [0, 0.13, 0] });
    cityGate(W, city, 0, 0, 0, 1.15, { stone: 0x060402, trim: 0x050302 });
    for (let i = 0; i < 5; i++) {
        house(W, city, -34 + i * 17 + W.rr(-4, 4), 0, W.rr(-14, 6), 0.85 + W.r() * 0.4, { mud: 0x060402 });
    }
    W.backdrop(city);

    /* flock: sheep grazing */
    sheep(W, group, 2.0, 0, -7.9, W.r() * 6, 1.17);
    sheep(W, group, 10.4, 0, -5.8, W.r() * 6, 1.06);
    sheep(W, group, 14.8, 0, 2.1, W.r() * 6, 0.84);
    sheep(W, group, 7.3, 0, 1.9, W.r() * 6, 1.10);

    well(W, group, 1.6, 0, 4.0, );

    /* hero: the standing stone */
    pillar(W, group, 0, 0, 11, 1.15, { stone: 0x060402 });
    W.disc([0, 6, -1], 5, 0x22152f, 0.3);

    /* figures */
    person(W, group, [-5, 0, 16], { robe: 0x1a1024, head: 'wrap', wrap: 0x1e1229, wrapTrim: 0x120b19, staff: 'planted', ry: -0.26, s: 1.19 });
    person(W, group, [4.5, 0, 17], { robe: 0x060402, head: 'wrap', wrap: 0x1e1229, wrapTrim: 0x120b19, staff: 'planted', ry: 0.67, s: 1.11 });
    person(W, group, [1, 0, 6], { robe: 0x8a6a44, head: 'wrap', wrap: 0x1e1229, wrapTrim: 0x120b19, staff: 'planted', ry: -0.32, s: 1.00 });

    /* birds: slow circles high above */
    birds(W, group, 7, 55, { y: 26 });

    return W.finish();
}

export default { build };
